import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

RC_PARAMS = {
    "font.size": 9,
    "axes.labelsize": 9,
    "axes.titlesize": 9,
    "xtick.labelsize": 8,
    "ytick.labelsize": 8,
    "legend.fontsize": 8,
    "axes.linewidth": 0.8,
    "xtick.major.width": 0.8,
    "ytick.major.width": 0.8,
}

FIGSIZE = (3.4, 2.6)
PALETTE = ["#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#8C564B", "#000000"]
RECEDED_ALPHA = 0.4

DATA_PATH = "data/benchmarks.csv"
X_FIELD = "model"
Y_FIELD = "latency_ms"
STEM = "05-latency-ranking"
FORMATS = ["png", "svg", "pdf"]
DPI = 600


def load():
    return pd.read_csv(DATA_PATH)


def aggregate(df):
    keys = [X_FIELD]
    return df.groupby(keys, as_index=False)[Y_FIELD].mean()


def draw(ax, df):
    frame = aggregate(df)
    categories = list(dict.fromkeys(frame[X_FIELD].tolist()))
    positions = np.arange(len(categories))
    subset = frame.set_index(X_FIELD).reindex(categories)
    ax.barh(positions, subset[Y_FIELD].to_numpy(), 0.7, color=PALETTE[0], zorder=2)
    ax.set_yticks(positions)
    ax.set_yticklabels([str(value) for value in categories])


def finish(fig, ax):
    ax.set_ylabel("Model")
    ax.set_xlabel("Latency (ms)")
    ax.set_xlim(left=0)
    ax.set_title("Inference cost")
    ax.grid(False)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    fig.tight_layout()


def main():
    df = load()
    with plt.rc_context(RC_PARAMS):
        fig, ax = plt.subplots(figsize=FIGSIZE)
        draw(ax, df)
        finish(fig, ax)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            kwargs = {"bbox_inches": "tight"}
            if fmt == "png":
                kwargs["dpi"] = DPI
            fig.savefig(path, **kwargs)
            print(f"wrote {path}")
    plt.close(fig)


if __name__ == "__main__":
    main()
